PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT (COUNT(DISTINCT ?liitaLemma) AS ?count)
WHERE {
  VALUES ?liitaLemmaType { lila:Lemma lila:Hypolemma }
  ?liitaLemma a ?liitaLemmaType .
  VALUES ?liitaLemmaType { lila:Lemma lila:Hypolemma }
  ?liitaLemma a ?liitaLemmaType .
  ?elitaLemma ontolex:canonicalForm ?liitaLemma .
  ?elitaLemma elita:HasEmotion ?emotion .

  ?emotion rdfs:label ?emotionLabel .
  ?itToSicEntry ontolex:canonicalForm ?liitaLemma ;
               vartrans:translatableAs ?sicEntry .
  ?sicEntry ontolex:canonicalForm ?sicLemma .
  ?sicLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
           ontolex:writtenRep ?sicWR .
  ?itToParEntry ontolex:canonicalForm ?liitaLemma ;
               vartrans:translatableAs ?parEntry .
  ?parEntry ontolex:canonicalForm ?parLemma .
  ?parLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
           ontolex:writtenRep ?parWR .
}

results.gold_sparql:
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?polysemous (COUNT(*) AS ?adjectiveCount) (AVG(?emotionCount) AS ?avgEmotions) WHERE {
  { SELECT ?italianLemma (COUNT(DISTINCT ?sense) AS ?senseCount) (COUNT(DISTINCT ?emotion) AS ?emotionCount) WHERE {
      SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
        ?word ontolex:sense ?sense ; lexinfo:partOfSpeech [ rdfs:label ?posLabel ] .
        FILTER(STR(?posLabel) = "adjective")
      }
      ?word ontolex:canonicalForm ?italianLemma .
      GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) }
      ?emotionEntry ontolex:canonicalForm ?italianLemma ; elita:HasEmotion ?emotion . ?emotion rdfs:label ?emotionLabel .
  } GROUP BY ?italianLemma }
  BIND(IF(?senseCount > 1, "yes", "no") AS ?polysemous)
}
GROUP BY ?polysemous
